<?php
declare(strict_types=1);
namespace App\Services\Hrd;use App\Enums\Hrd\AttendanceStatus;use App\Models\Personnel;use App\Services\Settings\ApplicationSettingService;use Carbon\CarbonImmutable;
class PayrollCalculator{public function __construct(private ApplicationSettingService $settings){}public function divisor(CarbonImmutable $start):int{return $start->daysInMonth;}public function calculate(Personnel $personnel,CarbonImmutable $start,CarbonImmutable $end,float $allowance=0,float $deduction=0):array{$monthly=(float)($personnel->base_salary??0);$divisor=$this->divisor($start);$daily=round($monthly/$divisor,2);$attendances=$personnel->attendances()->with('lateRemark')->whereBetween('attendance_date',[$start,$end])->get();$paid=[AttendanceStatus::Present,AttendanceStatus::Late,AttendanceStatus::Sick,AttendanceStatus::Leave,AttendanceStatus::OfficialDuty];$days=$attendances->whereIn('status',$paid)->count();$base=$this->settings->get('hrd_payroll_by_attendance_enabled',false)?round($daily*$days,2):$monthly;$late=0.0;if($this->settings->get('hrd_payroll_auto_late_deduction_enabled',false))foreach($attendances as $a){if($a->late_minutes>0&&$a->lateRemark?->status!=='approved'){$shiftMinutes=$this->shiftMinutes($a->shift_number,$start);$late+=round($daily*((int)$a->late_minutes/$shiftMinutes),2);}}$total=max(0,round($base+$allowance-$deduction-$late,2));return compact('monthly','daily','days','base','allowance','deduction','late','total');}private function shiftMinutes(int $shift,CarbonImmutable $date):int{$start=CarbonImmutable::parse($date->toDateString().' '.$this->settings->get("hrd_shift_{$shift}_start",'07:00'));$end=CarbonImmutable::parse($date->toDateString().' '.$this->settings->get("hrd_shift_{$shift}_end",'15:00'));if($end<=$start)$end=$end->addDay();return max(1,$start->diffInMinutes($end));}}
